import React,{useState,useEffect,useCallback} from 'react';import {supabase} from '../lib/supabase';import {useAuth} from '../contexts/AuthContext';import toast from 'react-hot-toast';import {UserPlus,X,CheckCircle,XCircle,Edit2,MessageCircle,Smartphone,Trash2,TrendingUp,Copy} from 'lucide-react';
export default function Employees(){const {storeId,staff:currentStaff,user}=useAuth();const [employees,setEmployees]=useState([]);const [loading,setLoading]=useState(true);const [error,setError]=useState(null);const [showModal,setShowModal]=useState(false);const [editing,setEditing]=useState(null);const [form,setForm]=useState({full_name:'',email:'',phone:'',role:'cashier',pin_code:'1234'});const [createdEmployee,setCreatedEmployee]=useState(null);const [showShareModal,setShowShareModal]=useState(false);const isAdmin=currentStaff?.role==='admin';
const loadEmployees=useCallback(async()=>{if(!storeId)return;setError(null);try{const {data,error}=await supabase.from('staff').select('*').eq('store_id',storeId).order('created_at',{ascending:false});if(error)throw error;setEmployees(data||[]);}catch(err){setError(err.message);toast.error(err.message);}finally{setLoading(false);}},[storeId]);
useEffect(()=>{if(storeId)loadEmployees();},[storeId,loadEmployees]);
const handleSubmit=async e=>{e.preventDefault();if(!isAdmin)return toast.error('Admin only');if(editing){try{const {error}=await supabase.from('staff').update({full_name:form.full_name,phone:form.phone,role:form.role,pin_code:form.pin_code}).eq('id',editing.id);if(error)throw error;toast.success('Employee updated');setShowModal(false);setEditing(null);loadEmployees();setForm({full_name:'',email:'',phone:'',role:'cashier',pin_code:'1234'});}catch(err){toast.error(err.message);}return;}
console.log('Creating employee...');const {data:{session:adminSession}}=await supabase.auth.getSession();if(!adminSession){toast.error('Session expired. Please log in again.');return;}const tempPassword='temp1234';try{console.log('Creating auth user:',form.email);const {data:authData,error:signUpError}=await supabase.auth.signUp({email:form.email,password:tempPassword,options:{data:{full_name:form.full_name}}});if(signUpError)throw signUpError;console.log('Restoring admin session...');const {error:restoreError}=await supabase.auth.setSession({access_token:adminSession.access_token,refresh_token:adminSession.refresh_token});if(restoreError){console.error('Session restore failed:',restoreError);toast.error('Session restoration failed. You may need to log in again.');setShowModal(false);loadEmployees();return;}console.log('Inserting staff record...');const {data:staffData,error:staffError}=await supabase.from('staff').insert({user_id:authData.user.id,store_id:storeId,full_name:form.full_name,email:form.email,phone:form.phone,role:form.role,pin_code:form.pin_code,is_active:true}).select().single();if(staffError)throw staffError;setCreatedEmployee({...staffData,tempPassword});setShowShareModal(true);setShowModal(false);setEditing(null);loadEmployees();setForm({full_name:'',email:'',phone:'',role:'cashier',pin_code:'1234'});toast.success('Employee created');}catch(err){toast.error('Failed: '+err.message);}};
const toggleActive=async(emp)=>{if(!isAdmin)return;const newStatus=!emp.is_active;const {error}=await supabase.from('staff').update({is_active:newStatus}).eq('id',emp.id);if(error)toast.error(error.message);else{toast.success(`Employee ${newStatus?'enabled':'disabled'}`);loadEmployees();}};
const deleteEmployee=async(emp)=>{if(!isAdmin)return;if(emp.id===currentStaff.id)return toast.error('Cannot delete yourself');if(!window.confirm(`Delete ${emp.full_name}?`))return;const {error}=await supabase.from('staff').delete().eq('id',emp.id);if(error)toast.error(error.message);else{toast.success('Deleted');loadEmployees();}};
const promoteToAdmin=async(emp)=>{if(!isAdmin||emp.role==='admin')return;if(!window.confirm(`Promote ${emp.full_name} to admin?`))return;const {error}=await supabase.from('staff').update({role:'admin'}).eq('id',emp.id);if(error)toast.error(error.message);else{toast.success('Promoted');loadEmployees();}};
const openEdit=emp=>{setEditing(emp);setForm({full_name:emp.full_name,email:emp.email,phone:emp.phone||'',role:emp.role,pin_code:emp.pin_code||'1234'});setShowModal(true);};
const shareViaWhatsApp=()=>{if(!createdEmployee)return;const msg=`Hi ${createdEmployee.full_name}, your Bwanali POS account:\nEmail: ${createdEmployee.email}\nPassword: ${createdEmployee.tempPassword}\nLogin: ${window.location.origin}`;window.open(`https://wa.me/${createdEmployee.phone?.replace(/\D/g,'')}?text=${encodeURIComponent(msg)}`,'_blank');};
const shareViaSMS=()=>{if(!createdEmployee)return;const msg=`Hi ${createdEmployee.full_name}, Bwanali POS account: Email ${createdEmployee.email} Password ${createdEmployee.tempPassword} Login ${window.location.origin}`;window.open(`sms:${createdEmployee.phone}?body=${encodeURIComponent(msg)}`,'_blank');};
const copyToClipboard=()=>{navigator.clipboard?.writeText(`Email: ${createdEmployee.email}\nPassword: ${createdEmployee.tempPassword}`);toast.success('Copied');};
if(!isAdmin)return<div className="p-8 text-red-600">Access Denied</div>;if(loading)return<div className="p-8">Loading...</div>;
return(<div className="p-4 h-full overflow-y-auto"><div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 mb-6"><h1 className="text-2xl font-bold">Employees</h1><button onClick={()=>{setEditing(null);setForm({full_name:'',email:'',phone:'',role:'cashier',pin_code:'1234'});setShowModal(true);}} className="bg-green-600 text-white px-4 py-2 rounded-lg flex items-center gap-2"><UserPlus size={18}/>Add Employee</button></div>{error&&<div className="mb-4 p-4 bg-red-50 text-red-700 rounded-lg">{error}</div>}<div className="hidden md:block bg-white rounded-xl shadow overflow-hidden"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-gray-50 border-b"><tr><th className="p-3">Name</th><th className="p-3">Email</th><th className="p-3">Role</th><th className="p-3">Status</th><th className="p-3 text-center">Actions</th></tr></thead><tbody>{employees.length===0?<tr><td colSpan="5" className="p-8 text-center">No employees</td></tr>:employees.map(e=>(<tr key={e.id} className="border-b hover:bg-gray-50"><td className="p-3">{e.full_name}</td><td className="p-3">{e.email}</td><td className="p-3 capitalize">{e.role}</td><td className="p-3"><span className={`px-2 py-1 rounded-full text-xs ${e.is_active?'bg-green-100 text-green-800':'bg-red-100 text-red-800'}`}>{e.is_active?'Active':'Disabled'}</span></td><td className="p-3"><div className="flex gap-1 justify-center"><button onClick={()=>openEdit(e)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"><Edit2 size={16}/></button><button onClick={()=>toggleActive(e)} className={`p-1.5 rounded ${e.is_active?'text-red-600 hover:bg-red-50':'text-green-600 hover:bg-green-50'}`}>{e.is_active?<XCircle size={16}/>:<CheckCircle size={16}/>}</button>{e.role!=='admin'&&<button onClick={()=>promoteToAdmin(e)} className="p-1.5 text-purple-600 hover:bg-purple-50 rounded"><TrendingUp size={16}/></button>}<button onClick={()=>deleteEmployee(e)} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><Trash2 size={16}/></button></div></td></tr>))}</tbody></table></div></div><div className="md:hidden space-y-3">{employees.map(e=>(<div key={e.id} className="bg-white rounded-lg shadow p-4"><div className="flex justify-between items-start"><div><h3 className="font-medium">{e.full_name}</h3><p className="text-sm text-gray-500">{e.email}</p><p className="text-xs text-gray-400 capitalize">{e.role}</p></div><span className={`text-xs px-2 py-1 rounded-full ${e.is_active?'bg-green-100 text-green-800':'bg-red-100 text-red-800'}`}>{e.is_active?'Active':'Disabled'}</span></div><div className="mt-4 flex gap-2 justify-end border-t pt-3"><button onClick={()=>openEdit(e)} className="p-2 bg-blue-50 text-blue-600 rounded-lg"><Edit2 size={18}/></button><button onClick={()=>toggleActive(e)} className={`p-2 rounded-lg ${e.is_active?'bg-red-50 text-red-600':'bg-green-50 text-green-600'}`}>{e.is_active?<XCircle size={18}/>:<CheckCircle size={18}/>}</button>{e.role!=='admin'&&<button onClick={()=>promoteToAdmin(e)} className="p-2 bg-purple-50 text-purple-600 rounded-lg"><TrendingUp size={18}/></button>}<button onClick={()=>deleteEmployee(e)} className="p-2 bg-red-50 text-red-600 rounded-lg"><Trash2 size={18}/></button></div></div>))}</div>{showModal&&(<div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"><div className="bg-white rounded-xl w-full max-w-md max-h-[90vh] overflow-auto"><div className="p-4 border-b flex justify-between"><h2 className="text-lg font-bold">{editing?'Edit':'Add'} Employee</h2><button onClick={()=>setShowModal(false)} className="p-1"><X/></button></div><form onSubmit={handleSubmit} className="p-4 space-y-4"><input placeholder="Full Name" value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})} className="w-full p-3 border rounded" required/>{!editing&&<input type="email" placeholder="Email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="w-full p-3 b